// Writes internal/gateway/prompts_gen.go: every fixed prompt text of
// gateway/prompts.ts and gateway/backfill.ts as a Go constant, taken from the
// TS module itself so the prompts stay verbatim. The texts that wrap a
// container name (peopleRules, peopleBackfillSystem) are split around a
// marker into a prefix and a suffix.
//
// Run from apps/app: npx tsx ../server/testdata/gen/prompts-gen.ts
import fs from "node:fs"
import path from "node:path"
import { BACKFILL_SYSTEM } from "../../../app/src/server/gateway/backfill.ts"
import { ASK_SYSTEM, EXTRACT_DATES, EXTRACT_SYSTEM, JSON_ONLY, OLD_DOCUMENT_DAYS, peopleBackfillSystem, peopleRules, PROFILE_SYSTEM } from "../../../app/src/server/gateway/prompts.ts"

const out = path.resolve(import.meta.dirname, "../../internal/gateway/prompts_gen.go")
const MARK = "\u0001CONTAINER\u0001"

function split(text: string, name: string) {
  const quoted = JSON.stringify(MARK)
  const i = text.indexOf(quoted)
  if (i < 0 || text.indexOf(quoted, i + 1) >= 0) throw new Error(`${name}: marker not found exactly once`)
  return [text.slice(0, i), text.slice(i + quoted.length)] as const
}

const go = (s: string) => JSON.stringify(s)
const [rulesPre, rulesPost] = split(peopleRules(MARK), "peopleRules")
const [backfillPre, backfillPost] = split(peopleBackfillSystem(MARK), "peopleBackfillSystem")
const lines = [
  "// Code generated by testdata/gen/prompts-gen.ts from gateway/prompts.ts and gateway/backfill.ts. DO NOT EDIT.",
  "",
  "package gateway",
  "",
  `// OldDocumentDays is OLD_DOCUMENT_DAYS.`,
  `const OldDocumentDays = ${OLD_DOCUMENT_DAYS}`,
  "",
  `const JSONOnly = ${go(JSON_ONLY)}`,
  "",
  `const ExtractDates = ${go(EXTRACT_DATES)}`,
  "",
  `const ExtractSystem = ${go(EXTRACT_SYSTEM)}`,
  "",
  `const ProfileSystem = ${go(PROFILE_SYSTEM)}`,
  "",
  `const AskSystem = ${go(ASK_SYSTEM)}`,
  "",
  `const BackfillSystem = ${go(BACKFILL_SYSTEM)}`,
  "",
  `const peopleRulesPrefix = ${go(rulesPre)}`,
  "",
  `const peopleRulesSuffix = ${go(rulesPost)}`,
  "",
  `const peopleBackfillPrefix = ${go(backfillPre)}`,
  "",
  `const peopleBackfillSuffix = ${go(backfillPost)}`,
  "",
]
fs.writeFileSync(out, lines.join("\n"))
console.log(`wrote ${out}`)
